CREATE TYPE "ApplicantStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TYPE "PaymentMethod" AS ENUM ('TRANSFER','CASH');
CREATE TABLE "applicants" ("applicant_id" TEXT NOT NULL,"registration_no" VARCHAR(40) NOT NULL,"full_name" VARCHAR(150) NOT NULL,"gender" "Gender" NOT NULL,"birth_place" VARCHAR(100) NOT NULL,"birth_date" DATE NOT NULL,"national_id" VARCHAR(30) NOT NULL,"email" VARCHAR(180) NOT NULL,"student_phone" VARCHAR(30) NOT NULL,"student_whatsapp" VARCHAR(30) NOT NULL,"parent_phone" VARCHAR(30) NOT NULL,"program_id" TEXT NOT NULL,"payment_proof_url" VARCHAR(500),"payment_method" "PaymentMethod" NOT NULL,"status" "ApplicantStatus" NOT NULL DEFAULT 'PENDING',"rejection_reason" VARCHAR(500),"reviewed_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL,CONSTRAINT "applicants_pkey" PRIMARY KEY ("applicant_id"),CONSTRAINT "applicants_program_id_fkey" FOREIGN KEY ("program_id") REFERENCES "programs"("program_id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "applicants_registration_no_key" ON "applicants"("registration_no"); CREATE UNIQUE INDEX "applicants_national_id_key" ON "applicants"("national_id"); CREATE INDEX "applicants_status_created_at_idx" ON "applicants"("status","created_at"); CREATE INDEX "applicants_program_id_idx" ON "applicants"("program_id");
